/** Whether a car's windows can be closed and opened remotely. */
export interface WindowsFeatures {
  /** Whether the car can close its windows remotely. */
  readonly close_available: boolean;
  /** Whether the car can open its windows remotely (to a vent crack). */
  readonly open_available: boolean;
}

/** Whether a car's trunk can be opened and closed remotely. */
export interface TrunkFeatures {
  /** Whether the trunk can be opened remotely. */
  readonly open_available: boolean;
  /** Whether the trunk can be closed remotely. */
  readonly close_available: boolean;
}

/** What each feature of a car offers. */
export interface CarFeatures {
  readonly lock: FeatureAvailability;
  readonly hvac: HvacFeatures;
  readonly seat: SeatFeatures;
  readonly steering: FeatureAvailability;
  readonly battery: FeatureAvailability;
  readonly finder: FinderFeatures;
  readonly windows: WindowsFeatures;
  readonly trunk: TrunkFeatures;
}

/** pyBYD's reply models by name: what `parseModel` returns for each. */
export interface Models {
  ClimateBooking: ClimateBooking;
  BookingList: BookingList;
  ChargingStatus: ChargingStatus;
  CommandGateRule: CommandGateRule;
  CommandGateVerdict: CommandGateVerdict;
  RemoteControlResult: RemoteControlResult;
  CommandAck: CommandAck;
  ChargeChangeResult: ChargeChangeResult;
  CommandAckEvent: CommandAckEvent;
  CommandLifecycleEvent: CommandLifecycleEvent;
  CommandAckDiagnostics: CommandAckDiagnostics;
  VerifyControlPasswordResponse: VerifyControlPasswordResponse;
  EnergyConsumptionGraph: EnergyConsumptionGraph;
  CumulativeEnergyConsumption: CumulativeEnergyConsumption;
  NearestEnergyConsumption: NearestEnergyConsumption;
  EnergyConsumption: EnergyConsumption;
  GpsInfo: GpsInfo;
  HvacStatus: HvacStatus;
  LatestConfigFunction: LatestConfigFunction;
  VehicleLatestConfig: VehicleLatestConfig;
  VehicleCapabilities: VehicleCapabilities;
  VehicleMsgItemInfo: VehicleMsgItemInfo;
  VehicleMsgListResponse: VehicleMsgListResponse;
  OtaUpgradeResult: OtaUpgradeResult;
  OtaUpgradeInfo: OtaUpgradeInfo;
  PushSwitch: PushSwitch;
  PushNotificationState: PushNotificationState;
  VehicleRealtimeData: VehicleRealtimeData;
  SmartChargeDto: SmartChargeDto;
  SmartJourneyDto: SmartJourneyDto;
  SmartChargingSchedule: SmartChargingSchedule;
  AcCurrentLimit: AcCurrentLimit;
  StandbyPlanCommand: StandbyPlanCommand;
  StandbyPlan: StandbyPlan;
  StandbyPlanList: StandbyPlanList;
  StandbyPlanRunResult: StandbyPlanRunResult;
  EmpowerRange: EmpowerRange;
  EmpowerDetail: EmpowerDetail;
  Vehicle: Vehicle;
}

/** The options of `seedVehicleMetadata`. */
export interface SeedOptions {
  /** The model's name. */
  modelName?: string | null | undefined;
}

/** The options of `getVehicleCapabilities`. */
export interface CapabilitiesOptions {
  /** Fetch again even when cached. Default `false`. */
  forceRefresh?: boolean | undefined;
}

/** The options of `getVehicleRealtime`, `getGpsInfo`. */
export interface PollOptions {
  /** HTTP polls after the MQTT wait. Default `10`. */
  pollAttempts?: number | undefined;
  /** Seconds slept before each poll. Default `1.5`. */
  pollInterval?: number | undefined;
  /** Seconds to wait for the MQTT push; the config's `mqtt_timeout` when null. */
  mqttTimeout?: number | null | undefined;
  /** "Data unavailable" answers in a row that end the polling. Default `2`. */
  signalRetries?: number | undefined;
}

/** The options of `getAcCurrentLimit`. */
export interface AcCurrentLimitOptions {
  /** The powertrain; the vehicle's own when null. */
  energyType?: EnergyType | null | undefined;
}

/** The options of `setPushState`. */
export interface PushStateOptions {
  /** The notification type; 701 is the vehicle status push. Default `701`. */
  pushType?: number | undefined;
}

/** The options of `getNotifications`. */
export interface NotificationOptions {
  /** Vehicle or system messages. Default `1`. */
  category?: NotificationCategory | undefined;
}

/** The options of `setOtaAutoUpgrade`. */
export interface OtaUpgradeOptions {
  /** When the night upgrade runs, `H:mm`. Default `"2:00"`. */
  autoUpgradeTime?: string | undefined;
  /** The control PIN for this command; the config's `control_pin` when null. */
  commandPwd?: string | null | undefined;
}

/** The options of `getEmpowerDetail`. */
export interface EmpowerDetailOptions {
  /** The grant ID; the cached vehicle's when null. */
  empowerId?: number | null | undefined;
}

/** The options of `saveStandbyPlan`, `createStandbyPlan`. */
export interface StandbyScheduleOptions {
  /**
   * The schedule to save; null keeps the plan's current schedule on save, or leaves a new plan
   * unscheduled.
   */
  schedule?: StandbySchedule | null | undefined;
}

/** The options of `runStandbyPlan`. */
export interface RunStandbyPlanOptions {
  /** How many times `send-result` is polled. Default `10`. */
  pollAttempts?: number | undefined;
  /** Seconds between polls. Default `1.5`. */
  pollInterval?: number | undefined;
}

/**
 * The options of `verifyCommandAccess`, `lock`, `unlock`, `stopClimate`, `flashLights`,
 * `closeWindows`, `openWindows`, `findCar`, `openTrunk`, `closeTrunk`, `startClimate`,
 * `scheduleClimate`, `setSeatClimate`, `setBatteryHeat`.
 */
export interface CommandOptions {
  /** The control PIN for this command; the config's `control_pin` when null. */
  commandPwd?: string | null | undefined;
}

/** The options of `saveChargingSchedule`. */
export interface SaveScheduleOptions {
  /** Whether the schedule is active. Default `true`. */
  enabled?: boolean | undefined;
  /** Seconds to wait for the MQTT push; the config's `mqtt_timeout` when null. */
  mqttTimeout?: number | null | undefined;
  /** HTTP polls after the MQTT wait. Default `10`. */
  pollAttempts?: number | undefined;
  /**
   * Seconds slept before each poll; null for the official app's 33 s ladder (1, 0.5, 0.5, 2, 2,
   * 2, 5, 5, 5, 10).
   */
  pollInterval?: number | null | undefined;
}

/** The options of `startCharging`, `stopCharging`. */
export interface ChargePollOptions {
  /** Seconds to wait for the MQTT push; the config's `mqtt_timeout` when null. */
  mqttTimeout?: number | null | undefined;
  /** HTTP polls after the MQTT wait. Default `10`. */
  pollAttempts?: number | undefined;
  /**
   * Seconds slept before each poll; null for the official app's 33 s ladder (1, 0.5, 0.5, 2, 2,
   * 2, 5, 5, 5, 10).
   */
  pollInterval?: number | null | undefined;
}

/** The options of `saveChargingSchedule`. */
export interface CarScheduleOptions {
  /** Whether the schedule is active. Default `true`. */
  enabled?: boolean | undefined;
}

/** The options of `handleMqttStatusPush`. */
export interface StatusPushOptions {
  /** The push's raw HVAC section, when present. */
  hvac?: JsonObject | null | undefined;
  /** The push's raw charging section, when present. */
  charging?: JsonObject | null | undefined;
}

/** The options of `start`. */
export interface ClimateOptions {
  /** Target temperature in °C. Default `21.0`. */
  temperature?: number | undefined;
  /** Run time in minutes: 10, 15, 20, 25 or 30. Default `20`. */
  duration?: number | undefined;
  /** 1 fresh air, 2 recirculate; null keeps a running session's setting. */
  cycleMode?: number | null | undefined;
  /** Fan speed 1-7; null keeps a running session's speed. */
  fanLevel?: number | null | undefined;
}
